<script setup lang="ts">
import type { AnalyticsReport } from '#shared/types/analytics'
const from=ref(''),to=ref('')
const applied=ref<{from?:string;to?:string}>({})
const {data,error,status}=await useFetch<AnalyticsReport>('/api/admin/analytics',{query:applied})
function apply(){applied.value={...(from.value?{from:from.value}:{}),...(to.value?{to:to.value}:{})}}
const duration=computed(()=>data.value?.averageResolutionMinutes==null?'Нет решений':`${Math.round(data.value.averageResolutionMinutes)} мин`)
</script>
<template><div class="container knowledge"><h1>Аналитика</h1><p>Заявки, созданные за период (UTC). SLA — доля решений, выполненных до зафиксированного срока.</p><form class="analytics-period" @submit.prevent="apply"><UiInput v-model="from" label="С даты" type="date"/><UiInput v-model="to" label="По дату включительно" type="date"/><UiButton type="submit" :disabled="status==='pending'">Применить период</UiButton></form><p v-if="error" role="alert">{{toUiError(error).message}}</p><template v-if="data"><div class="analytics-stats"><section class="panel knowledge-card"><p>Всего заявок</p><h2>{{data.total}}</h2></section><section class="panel knowledge-card"><p>Закрыто</p><h2>{{data.statuses.closed||0}}</h2></section><section class="panel knowledge-card"><p>SLA соблюдён</p><h2>{{data.slaPercent===null?'Нет решений':data.slaPercent+'%'}}</h2><p>Измерено решений: {{data.slaMeasured}}</p></section><section class="panel knowledge-card"><p>Среднее решение</p><h2>{{duration}}</h2></section></div><section class="panel knowledge-card"><h2>Заявки по статусам</h2><div v-for="(count,key) in data.statuses" :key="key" class="chart-row"><span>{{STATUS_LABELS[key as keyof typeof STATUS_LABELS]||key}}</span><meter :value="count" :max="Math.max(data.total,1)" :aria-label="String(key)"/><span>{{count}}</span></div></section><section class="panel knowledge-card"><h2>Текущая загрузка исполнителей</h2><p v-for="agent in data.agents" :key="agent.id">{{agent.name}} — {{agent.count}} активных заявок</p></section></template></div></template>
<style scoped>.analytics-period{display:flex;flex-wrap:wrap;gap:16px;align-items:end}.analytics-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.chart-row{display:grid;grid-template-columns:minmax(0,150px) minmax(20px,400px) 30px;gap:12px;align-items:center}meter{width:100%;height:14px}meter::-webkit-meter-bar{background:var(--c-surface);border:0;border-radius:8px}meter::-webkit-meter-optimum-value{background:linear-gradient(90deg,#635bff,#b17dff);border-radius:8px}meter::-moz-meter-bar{background:#8b6cff}@media(max-width:767px){.analytics-stats{grid-template-columns:1fr 1fr}}@media(max-width:399px){.analytics-stats{grid-template-columns:1fr}}
</style>
